/// url = 'http://octofhir.com/ccda-fhir/StructureMap/fhir-participants-to-cda'
/// name = 'FhirParticipantsToCda'
/// title = 'FHIR R4 participants to CDA'
/// status = 'active'
/// description = 'Practitioner, Organization and Device to CDA assigned authors, entities and organizations; the author agents of US Core 6.1.0 Provenance to entry authors, after "CDA ↔ FHIR Provenance" of the C-CDA on FHIR 2.0.0 mapping guidance.'

map "http://octofhir.com/ccda-fhir/StructureMap/fhir-participants-to-cda" = "FhirParticipantsToCda"

uses "http://hl7.org/fhir/StructureDefinition/Practitioner" alias Practitioner as source
uses "http://hl7.org/fhir/StructureDefinition/PractitionerRole" alias PractitionerRole as source
uses "http://hl7.org/fhir/StructureDefinition/Organization" alias Organization as source
uses "http://hl7.org/fhir/StructureDefinition/Device" alias Device as source
uses "http://hl7.org/fhir/StructureDefinition/Provenance" alias Provenance as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/AssignedAuthor" alias AssignedAuthor as target
uses "http://hl7.org/cda/stds/core/StructureDefinition/AssignedEntity" alias AssignedEntity as target
uses "http://hl7.org/cda/stds/core/StructureDefinition/Organization" alias CdaOrganization as target
uses "http://hl7.org/cda/stds/core/StructureDefinition/CustodianOrganization" alias CustodianOrganization as target
uses "http://hl7.org/fhir/StructureDefinition/Reference" alias Reference as source
uses "http://hl7.org/fhir/StructureDefinition/Annotation" alias Annotation as source
uses "http://hl7.org/fhir/StructureDefinition/Bundle" alias Bundle as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Author" alias Author as target
uses "http://hl7.org/cda/stds/core/StructureDefinition/Act" alias Act as target
uses "http://hl7.org/cda/stds/core/StructureDefinition/CE" alias CE as target

imports "http://octofhir.com/ccda-fhir/StructureMap/fhir-datatypes-to-cda"

group PractitionerToAssignedAuthor(source src : Practitioner, target tgt : AssignedAuthor) {
  src.identifier as identifier -> tgt.id as id then IdentifierToII(identifier, id);
  src where (identifier.empty()) -> tgt.id as id, id.nullFlavor = 'NI';
  src.address as address -> tgt.addr as addr then AddressToAD(address, addr);
  src.telecom as telecom -> tgt.telecom as tel then ContactPointToTEL(telecom, tel);
  src where (address.empty()) -> tgt.addr as addr, addr.nullFlavor = 'NI';
  src where (telecom.empty()) -> tgt.telecom as tel, tel.nullFlavor = 'NI';
  // A person with a name; a practitioner known only by its ids has none here.
  src where (name.where(family.exists() or given.exists() or text.exists()).exists()) -> tgt.assignedPerson as person then {
    src.name as name where (family.exists() or given.exists() or text.exists()) -> person.name as pn then HumanNameToPN(name, pn);
  };
}

group PractitionerToAssignedEntity(source src : Practitioner, target tgt : AssignedEntity) {
  src.identifier as identifier -> tgt.id as id then IdentifierToII(identifier, id);
  src where (identifier.empty()) -> tgt.id as id, id.nullFlavor = 'NI';
  src.address as address -> tgt.addr as addr then AddressToAD(address, addr);
  src.telecom as telecom -> tgt.telecom as tel then ContactPointToTEL(telecom, tel);
  src where (address.empty()) -> tgt.addr as addr, addr.nullFlavor = 'NI';
  src where (telecom.empty()) -> tgt.telecom as tel, tel.nullFlavor = 'NI';
  // A person with a name; a practitioner known only by its ids has none here.
  src where (name.where(family.exists() or given.exists() or text.exists()).exists()) -> tgt.assignedPerson as person then {
    src.name as name where (family.exists() or given.exists() or text.exists()) -> person.name as pn then HumanNameToPN(name, pn);
  };
}

group DeviceToAssignedAuthor(source src : Device, source bundle : Bundle, target tgt : AssignedAuthor) {
  src.identifier as identifier -> tgt.id as id then IdentifierToII(identifier, id);
  src where (identifier.empty()) -> tgt.id as id, id.nullFlavor = 'NI';
  src -> tgt.assignedAuthoringDevice as device then {
    src.deviceName first as name then {
      name.name as n -> device.manufacturerModelName as model, model.xmlText = n;
    };
    src.version first as version then {
      version.value as v -> device.softwareName as software, software.xmlText = v;
    };
  };
  src -> tgt.addr as addr, addr.nullFlavor = 'NI';
  src -> tgt.telecom as tel, tel.nullFlavor = 'NI';
  src.owner as ref then {
    bundle.entry as entry where (fullUrl = %ref.reference) then {
      entry.resource : Organization as organization -> tgt.representedOrganization as org then OrganizationToOrganization(organization, org);
    };
  };
}

group OrganizationToOrganization(source src : Organization, target tgt : CdaOrganization) {
  src.identifier as identifier -> tgt.id as id then IdentifierToII(identifier, id);
  src.name as name -> tgt.name as on, on.item as item, item.xmlText = name;
  src.telecom as telecom -> tgt.telecom as tel then ContactPointToTEL(telecom, tel);
  src.address as address -> tgt.addr as addr then AddressToAD(address, addr);
  src where (telecom.empty()) -> tgt.telecom as tel, tel.nullFlavor = 'NI';
  src where (address.empty()) -> tgt.addr as addr, addr.nullFlavor = 'NI';
}

group OrganizationToCustodian(source src : Organization, target tgt : CustodianOrganization) {
  src.identifier as identifier -> tgt.id as id then IdentifierToII(identifier, id);
  src where (identifier.empty()) -> tgt.id as id, id.nullFlavor = 'NI';
  src.name as name -> tgt.name as on, on.item as item, item.xmlText = name;
  src.telecom first as telecom -> tgt.telecom as tel then ContactPointToTEL(telecom, tel);
  src where (telecom.empty()) -> tgt.telecom as tel, tel.nullFlavor = 'NI';
  src.address first as address -> tgt.addr as addr then AddressToAD(address, addr);
  src where (address.empty()) -> tgt.addr as addr, addr.nullFlavor = 'NI';
}

// The Practitioner a reference names, as the author (C-CDA Author Participation) of `owner`,
// at `time` (a FHIR dateTime, or 'UNK' when not known).
group ReferenceToAuthor(source ref : Reference, source bundle : Bundle, source time, target owner) {
  bundle.entry as entry where (fullUrl = %ref.reference) then {
    entry.resource : Practitioner as practitioner -> owner.author as author, author.templateId as template, template.root = '2.16.840.1.113883.10.20.22.4.119' then {
      time as t where (t.toString() != 'UNK') -> author.time as at, at.value = t;
      time as t where (t.toString() = 'UNK') -> author.time as at, at.nullFlavor = 'UNK';
      practitioner -> author.assignedAuthor as assigned then PractitionerToAssignedAuthor(practitioner, assigned);
    };
    entry.resource : PractitionerRole as role -> owner.author as author, author.templateId as template, template.root = '2.16.840.1.113883.10.20.22.4.119' then {
      time as t where (t.toString() != 'UNK') -> author.time as at, at.value = t;
      time as t where (t.toString() = 'UNK') -> author.time as at, at.nullFlavor = 'UNK';
      role -> author.assignedAuthor as assigned then RoleToAssignedAuthor(role, bundle, assigned);
    };
  };
}

// The authors US Core Provenance gives a resource (mapping guidance, "CDA ↔ FHIR Provenance"):
// each author agent of a Provenance whose target is `ownUrl` (the resource's fullUrl; references
// point at fullUrls before the maps run), as an author (C-CDA Author Participation) of
// `statement` at the recorded time. An agent the resource names itself is left to the domain
// map, which writes it from the resource (`.recorder`, `.requester`, …): `written` holds those
// references, each between `|`.
group ProvenanceAuthors(source ownUrl : string, source bundle : Bundle, source written : string, target statement) {
  bundle.entry as provenanceEntry then {
    provenanceEntry.resource : Provenance as provenance where (target.where(reference = %ownUrl).exists()) then {
      provenance.agent as agent where (type.coding.where(system = 'http://terminology.hl7.org/CodeSystem/provenance-participant-type' and code = 'author').exists() and iif(%written.contains('|' + who.reference + '|'), false, true)) -> evaluate(provenance, iif(recorded.hasValue(), recorded, 'UNK')) as time then AgentToAuthor(agent, bundle, time, statement);
    };
  };
}

// A Provenance agent as an author at `time` (a FHIR instant, or 'UNK'): who it is, and on whose
// behalf as the represented organization when who does not say it already.
group AgentToAuthor(source agent, source bundle : Bundle, source time, target statement) {
  agent.who as who then {
    bundle.entry as entry where (fullUrl = %who.reference) then {
      entry.resource : Practitioner as practitioner -> statement.author as author, author.templateId as template, template.root = '2.16.840.1.113883.10.20.22.4.119' then {
        time then AuthorTime(time, author);
        practitioner -> author.assignedAuthor as assigned then {
          practitioner then PractitionerToAssignedAuthor(practitioner, assigned);
          agent then OnBehalfOf(agent, bundle, assigned);
        };
      };
      entry.resource : PractitionerRole as role -> statement.author as author, author.templateId as template, template.root = '2.16.840.1.113883.10.20.22.4.119' then {
        time then AuthorTime(time, author);
        role -> author.assignedAuthor as assigned then {
          role then RoleToAssignedAuthor(role, bundle, assigned);
          role where (organization.empty()) then OnBehalfOf(agent, bundle, assigned);
        };
      };
      entry.resource : Device as device -> statement.author as author, author.templateId as template, template.root = '2.16.840.1.113883.10.20.22.4.119' then {
        time then AuthorTime(time, author);
        device -> author.assignedAuthor as assigned then {
          device then DeviceToAssignedAuthor(device, bundle, assigned);
          device where (owner.empty()) then OnBehalfOf(agent, bundle, assigned);
        };
      };
      // An organization alone, as the document's author has it (Author in document.map).
      entry.resource : Organization as organization -> statement.author as author, author.templateId as template, template.root = '2.16.840.1.113883.10.20.22.4.119' then {
        time then AuthorTime(time, author);
        organization -> author.assignedAuthor as assigned, assigned.id as id, id.nullFlavor = 'NA', assigned.representedOrganization as org then OrganizationToOrganization(organization, org);
      };
    };
  };
}

group AuthorTime(source time, target author : Author) {
  time as t where (t.toString() != 'UNK') -> author.time as at, at.value = t;
  time as t where (t.toString() = 'UNK') -> author.time as at, at.nullFlavor = 'UNK';
}

// The Organization an agent acted on behalf of, as the represented organization.
group OnBehalfOf(source agent, source bundle : Bundle, target assigned : AssignedAuthor) {
  agent.onBehalfOf as ref then {
    bundle.entry as entry where (fullUrl = %ref.reference) then {
      entry.resource : Organization as organization -> assigned.representedOrganization as org then OrganizationToOrganization(organization, org);
    };
  };
}

// A PractitionerRole as an assigned author: the Practitioner, the role's code, the Organization.
group RoleToAssignedAuthor(source role : PractitionerRole, source bundle : Bundle, target assigned : AssignedAuthor) {
  role.practitioner as ref then {
    bundle.entry as entry where (fullUrl = %ref.reference) then {
      entry.resource : Practitioner as practitioner then PractitionerToAssignedAuthor(practitioner, assigned);
    };
  };
  role where (practitioner.empty()) -> assigned.id as id, id.nullFlavor = 'NI';
  role.code first as code -> assigned.code = create('CE') as c then CodeableConceptToCD(code, c);
  role where (practitioner.empty()) then {
    role -> assigned.addr as addr, addr.nullFlavor = 'NI';
    role -> assigned.telecom as tel, tel.nullFlavor = 'NI';
  };
  role.organization as ref then {
    bundle.entry as entry where (fullUrl = %ref.reference) then {
      entry.resource : Organization as organization -> assigned.representedOrganization as org then OrganizationToOrganization(organization, org);
    };
  };
}

// The Practitioner or Organization a reference names, as a performer of `owner`.
group ReferenceToPerformer(source ref : Reference, source bundle : Bundle, target owner) {
  bundle.entry as entry where (fullUrl = %ref.reference) then {
    entry.resource : Practitioner as practitioner -> owner.performer as performer, performer.typeCode = 'PRF', performer.assignedEntity as entity then PractitionerToAssignedEntity(practitioner, entity);
    entry.resource : PractitionerRole as role -> owner.performer as performer, performer.typeCode = 'PRF', performer.assignedEntity as entity then RoleToAssignedEntity(role, bundle, entity);
    entry.resource : Organization as organization -> owner.performer as performer, performer.typeCode = 'PRF', performer.assignedEntity as entity, entity.id as id, id.nullFlavor = 'NA', entity.addr as addr, addr.nullFlavor = 'NI', entity.telecom as tel, tel.nullFlavor = 'NI', entity.representedOrganization as org then OrganizationToOrganization(organization, org);
  };
}

// Annotation → C-CDA Comment Activity, in an entryRelationship of `owner`.
group AnnotationToComment(source note : Annotation, target owner) {
  note.text as text -> owner.entryRelationship as relationship, relationship.typeCode = 'SUBJ', relationship.inversionInd = true, relationship.act as comment then {
    text -> comment.classCode = 'ACT', comment.moodCode = 'EVN';
    text -> comment.templateId as template, template.root = '2.16.840.1.113883.10.20.22.4.64';
    text -> comment.code as code, code.code = '48767-8', code.codeSystem = '2.16.840.1.113883.6.1', code.displayName = 'Annotation comment';
    text -> comment.text as t, t.xmlText = text, t.reference as ref, ref.nullFlavor = 'NI';
  };
}

// A PractitionerRole as an assigned entity: the Practitioner, the role's code, the Organization.
group RoleToAssignedEntity(source role : PractitionerRole, source bundle : Bundle, target entity : AssignedEntity) {
  role.practitioner as ref then {
    bundle.entry as entry where (fullUrl = %ref.reference) then {
      entry.resource : Practitioner as practitioner then PractitionerToAssignedEntity(practitioner, entity);
    };
  };
  role where (practitioner.empty()) then {
    role -> entity.id as id, id.nullFlavor = 'NI';
    role -> entity.addr as addr, addr.nullFlavor = 'NI';
    role -> entity.telecom as tel, tel.nullFlavor = 'NI';
  };
  role.code first as code -> entity.code = create('CE') as c then CodeableConceptToCD(code, c);
  role.organization as ref then {
    bundle.entry as entry where (fullUrl = %ref.reference) then {
      entry.resource : Organization as organization -> entity.representedOrganization as org then OrganizationToOrganization(organization, org);
    };
  };
}
